-- composition of rule kernels L:common_sub_expression_eliminate x L:simplify_expressions (datafusion), template not_exists
SELECT count(*) FROM (SELECT TRUE AS c0, 1.5::numeric AS c1) AS ka WHERE NOT EXISTS (SELECT 1 FROM (SELECT CASE a1.c4 WHEN make_array(1, 2, 3, 4) THEN 5e-324::float8 WHEN a1.c4 THEN 0.0::float8 ELSE 0.5::float8 END AS c0 FROM (t3 AS a1 INNER JOIN ti AS a2 ON (a1.c0 = a2.c0)) UNION ALL SELECT 100.0::float8 AS c0) AS kb);
-- pgfuzz:check kernel:not_exists SELECT CASE WHEN (SELECT count(*) FROM (SELECT CASE a1.c4 WHEN make_array(1, 2, 3, 4) THEN 5e-324::float8 WHEN a1.c4 THEN 0.0::float8 ELSE 0.5::float8 END AS c0 FROM (t3 AS a1 INNER JOIN ti AS a2 ON (a1.c0 = a2.c0)) UNION ALL SELECT 100.0::float8 AS c0) AS kb) = 0 THEN (SELECT count(*) FROM (SELECT TRUE AS c0, 1.5::numeric AS c1) AS ka) ELSE 0 END
